import { useState, useRef } from 'react';

const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://localhost:3000/'

};

const menu = {
  link1:{
    copy:'home',
    url: 'http://localhost:3000/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};


const Menu = () =>  {

  const [show, setShow] = useState(false);
  const ref = useRef(null);
  const toggle = () =>  ( setShow(!show));

return(
    <>
    <nav className='navbar navbar-expand-lg bg-body-tertiary fixed-top' role='navigation'>
      <div className='container-fluid'>
        <a className='navbar-brand' href={logo.href}>
          <img src={logo.url} alt={logo.alt} width={logo.width} />
        </a>
        <div className='navbar-expand-lg menu-links'>
            <a ref={ref} onClick={toggle} href={menu.link1.url}>{menu.link1.copy}</a> 
            <a ref={ref} onClick={toggle} href={menu.link2.url}>{menu.link2.copy}</a>
            <a ref={ref} onClick={toggle} href={menu.link3.url}>{menu.link3.copy}</a> 
            <a ref={ref} onClick={toggle} href={menu.link4.url}>{menu.link4.copy}</a> 
          </div>
        <button className='navbar-toggler' type='button' data-bs-toggle='collapse' data-bs-target='#navbarSupportedContent' aria-controls='navbarSupportedContent' aria-expanded='false' aria-label='Toggle navigation'  onClick={toggle}>
              <span className='navbar-toggler-icon'></span>
        </button>
        <div className='navbar-collapse flex-row-reverse'>
        {show &&  
          <div className='navbar-nav mr-auto menu-links'>
            <a ref={ref} onClick={toggle} href={menu.link1.url}>{menu.link1.copy}</a> 
            <a ref={ref} onClick={toggle} href={menu.link2.url}>{menu.link2.copy}</a>
            <a ref={ref} onClick={toggle} href={menu.link3.url}>{menu.link3.copy}</a> 
            <a ref={ref} onClick={toggle} href={menu.link4.url}>{menu.link4.copy}</a> 
          </div>
        }
        </div>
      </div>
    </nav>
    </>
  )

};



export default Menu;
